"""WW2 1944 tables for scripts/generate_roster.py (ERA-01 slice: US Army vs Wehrmacht, Western Front 1944).

Research: assets_src/research/ww2_1944_roster_sources.json (every unit number sourced there). Weapon penetration
tables below cite the Wikipedia gun articles fetched 2026-10-09. Figures given at 30 degrees from vertical are
converted to normal impact with the per-range ratio of the 8.8 cm KwK 43 article, which tabulates both:
100 m x1.15, 500 m x1.18, 1000 m x1.24, 1500 m x1.28, 2000 m x1.33.
"""
from __future__ import annotations

# 30-degree -> normal conversion by range (from the KwK 43 table: 233/202, 219/185, 204/165, 190/148, 176/132).
CONV = {100: 1.15, 457: 1.18, 500: 1.18, 914: 1.24, 1000: 1.24, 1372: 1.28, 1500: 1.28, 1829: 1.33, 2000: 1.33}


def at30(table):
    """[(range m, mm at 30 deg)] -> [[range, mm at normal]]."""
    return [[r, round(mm * CONV[r])] for r, mm in table]


